test('pre-fills a single argument', () => {
  const add = (a, b) => a + b;
  const add5 = partial(add, 5);
  expect(add5(3)).toBe(8);
});

test('pre-fills multiple arguments', () => {
  const sum3 = (a, b, c) => a + b + c;
  const sumFrom10 = partial(sum3, 10, 20);
  expect(sumFrom10(5)).toBe(35);
});

test('pre-fills all arguments', () => {
  const multiply = (a, b) => a * b;
  const triple = partial(multiply, 3, 4);
  expect(triple()).toBe(12);
});

test('does not mutate the original function', () => {
  const add = (a, b) => a + b;
  partial(add, 5);
  expect(add(1, 2)).toBe(3);
});

// __hidden__
test('works with a ternary function', () => {
  const greet = (greeting, name, punctuation) => `${greeting}, ${name}${punctuation}`;
  const hello = partial(greet, 'Hello');
  expect(hello('World', '!')).toBe('Hello, World!');
});

solution:
export function partial(fn, ...presetArgs) {
  return function(...laterArgs) {
    return fn(...presetArgs, ...laterArgs);
  };
}
